   161	fn parse_server_url(server_url: &str) -> Result<(String, u16, String), Box<dyn std::error::Error>> {
   162	    let rest = server_url
   163	        .strip_prefix("http://")
   164	        .ok_or_else(|| format!("only plain http:// is supported, got: {server_url}"))?;
   165	    let authority = rest.split('/').next().unwrap_or(rest);
   166	    let mut parts = authority.splitn(2, ':');
   167	    let host = parts.next().unwrap_or("127.0.0.1").to_string();
   168	    let port = parts
   169	        .next()
   170	        .map(str::parse)
   171	        .transpose()?
   172	        .unwrap_or(80u16);
   173	    Ok((host, port, authority.to_string()))
   174	}
   175	
   176	fn build_http_request(host_header: &str, body: &[u8]) -> Vec<u8> {
   177	    let headers = format!(
   178	        "POST /search HTTP/1.1\r\ncontent-type: application/json\r\naccept: */*\r\nhost: {host_header}\r\ncontent-length: {}\r\n\r\n",
   179	        body.len()
   180	    );
   181	
   182	    let mut request = Vec::with_capacity(headers.len() + body.len());
   183	    request.extend_from_slice(headers.as_bytes());
   184	    request.extend_from_slice(body);
   185	    request
   186	}
   187	
   188	fn run_worker(
   189	    host: &str,
   190	    port: u16,
   191	    requests: &[Vec<u8>],
   192	    request_indexes: &[usize],
   193	) -> io::Result<()> {
   194	    let mut stream = TcpStream::connect((host, port))?;
   195	    stream.set_nodelay(true)?;
   196	    let mut buffer = Vec::with_capacity(64 * 1024);
   197	
   198	    for &request_idx in request_indexes {
   199	        stream.write_all(&requests[request_idx])?;
   200	        read_response(&mut stream, &mut buffer)?;
   201	    }
   202	
   203	    Ok(())
   204	}
   205	
   206	fn read_response(stream: &mut TcpStream, buffer: &mut Vec<u8>) -> io::Result<()> {
   207	    loop {
   208	        if let Some(header_end) = find_header_end(buffer) {
   209	            let body_start = header_end + 4;
   210	            let content_length =
   211	                parse_content_length(&buffer[..header_end]).ok_or_else(bad_response_error)?;
   212	            let body_end = body_start
   213	                .checked_add(content_length)
   214	                .ok_or_else(bad_response_error)?;
   215	
   216	            if buffer.len() >= body_end {
   217	                consume_buffer(buffer, body_end);
   218	                return Ok(());
   219	            }
   220	        }
